{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C45"],
      "claim": "Alfentanil, the closest analogue sharing the propanamide and methoxymethyl-piperidine core, had an absolute oral bioavailability of 0.42 ± 0.15 in volunteers, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Fentanyl, a close N-phenylpropanamide piperidine analogue, had a mean oral bioavailability of 0.32 ± 0.1 after oral solution, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Pethidine, a piperidine opioid, had an absolute oral bioavailability of 0.52 in healthy subjects, supporting high oral bioavailability in this opioid piperidine class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Phenoperidine, a less transferable ester-containing piperidine opioid, had systemic bioavailability of 9.9%, a contradictory low-F data point outweighed by the closer alfentanil/fentanyl analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest analogues alfentanil and fentanyl have absolute oral bioavailability of 42% and 32%, respectively, strongly supporting F ≥ 20% for the sufentanil-like query. Low-F compounds such as phenoperidine, loperamide, and tilidine are structurally less transferable due to ester prodrug, P-gp efflux, or phenolic first-pass liabilities.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for sufentanil itself is present in the provided evidence; prediction relies on alfentanil and fentanyl analogues.",
    "Rifampin-induction records for alfentanil are not applicable to the baseline query.",
    "Sufentanil oral bioavailability may be borderline near 20%, so the exact threshold classification carries some uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

